if(location.pathname.replace(/\/$/,'')==='/tours'){
 const categories={cities:'Village Life',nature:'Backwaters',adventure:'Boat Rides',honeymoon:'Kerala Lunch',wildlife:'Local Crafts'};
 const cards=$$('a[href="/tour"]').filter(a=>$('h3',a));
 const filters=$$('[data-highlight],button,a').filter(e=>['All Tours',...Object.values(categories)].includes(e.textContent.trim())&&!e.closest('nav')&&!e.closest('footer')&&!e.closest('a[href="/tour"]'));
 function filter(label){cards.forEach(a=>{const text=a.textContent.toLowerCase();let show=label==='All Tours'||text.includes(label.toLowerCase());if(label==='Local Crafts')show=/weaving|coir|craft/.test(text);if(label==='Village Life')show=/weaving|coir|craft|village/.test(text);if(label==='Backwaters'||label==='Boat Rides')show=/boat|canal/.test(text);if(label==='Kerala Lunch')show=/lunch/.test(text);const wrapper=a.parentElement;wrapper.classList.toggle('client-hidden',!show)});filters.forEach(e=>{e.classList.toggle('client-filter-active',e.textContent.trim()===label);e.setAttribute('aria-pressed',String(e.textContent.trim()===label))})}
 filters.forEach(e=>{e.setAttribute('role','button');e.tabIndex=0;e.addEventListener('click',ev=>{ev.preventDefault();filter(e.textContent.trim())});e.addEventListener('keydown',ev=>{if(ev.key==='Enter')filter(e.textContent.trim())})});const q=new URLSearchParams(location.search).get('category');if(q&&categories[q])filter(categories[q]);
}
