if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const vo=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.play().catch(()=>{});else e.target.pause()}));$$('video').forEach(v=>{v.muted=true;vo.observe(v)})}
