// Match the reference's responsive page and layout variants without its CMS runtime.
const root=$('#main');if(root&&root.dataset.framerHydrateV2){try{const config=JSON.parse(root.dataset.framerHydrateV2);const breaks=config.breakpoints||[];const hashes=breaks.map(b=>'framer-'+b.hash);const elements=$$('[class]',root).filter(e=>hashes.some(h=>e.classList.contains(h)));const groups=[];for(let i=0;i<breaks.length;i+=3)groups.push(breaks.slice(i,i+3));function responsive(){elements.forEach(el=>{const group=groups.find(g=>g.some(b=>el.classList.contains('framer-'+b.hash)));if(!group)return;const selected=group.find(b=>matchMedia(b.mediaQuery).matches);if(selected){group.forEach(b=>el.classList.remove('framer-'+b.hash));el.classList.add('framer-'+selected.hash)}})}responsive();window.addEventListener('resize',responsive,{passive:true})}catch{}}
