$$('section[data-framer-name="Tours"]').filter(s=>$('[data-framer-name="Arrow Left"]',s)).forEach(section=>{let n=0;function show(i){n=(i+places.length)%places.length;$$('a[href="/location"]',section).filter(a=>$('h3',a)).forEach(a=>{const h=$('h3',a);h.textContent=places[n][0];const p=$$('p',a).find(p=>p.textContent.length>45);if(p)p.textContent=places[n][1]})}$$('[data-framer-name="Arrow Left"],[data-framer-name="Arrow Right"]',section).forEach(b=>{b.setAttribute('role','button');b.tabIndex=0;b.setAttribute('aria-label',b.dataset.framerName==='Arrow Left'?'Previous location':'Next location');const action=()=>show(n+(b.dataset.framerName==='Arrow Left'?-1:1));b.addEventListener('click',action);b.addEventListener('keydown',e=>{if(e.key==='Enter')action()})});$$('img[alt="Flag Image"]',section).forEach((img,i)=>{const b=img.parentElement;b.setAttribute('role','button');b.tabIndex=0;b.setAttribute('aria-label',places[i%5][0]);b.addEventListener('click',()=>show(i%5));b.addEventListener('keydown',e=>{if(e.key==='Enter')show(i%5)})})});
